// Limpio lo que llega del formulario y apunto qué falta, para registrarlo si la solicitud viene incompleta
const c = $('Configuración').first().json;
const idea = String($json.idea ?? '').trim();
const publico = String($json.publico ?? '').trim();
const email = String($json.email ?? '').trim().toLowerCase();
const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

const faltan = [];
if (idea.length < c.minCaracteresIdea) faltan.push(`idea de al menos ${c.minCaracteresIdea} caracteres (llegaron ${idea.length})`);
if (!publico) faltan.push('público objetivo');
if (!emailValido) faltan.push('email válido de quien lo pide');

return { json: { idea, publico, email: emailValido ? email : '', emailValido, faltan: faltan.join(', ') } };

