// Junto lo que necesita Claude: la solicitud, las fichas validadas de la base de conocimiento (RAG)
// y el gancho de los últimos posts publicados (memoria, para no repetirse)
const solicitud = $('Normalizar datos').first().json;
const registro = $('Registrar solicitud en Airtable').first().json;
const hilo = $('Abrir hilo en Slack').first().json.message.ts;

const fichas = $('Leer base de conocimiento').all().map((f) => ({ id: f.json.id, ...f.json.fields }));
const publicados = $('Leer últimos publicados').all()
  .filter((p) => p.json.id)
  .map((p) => String(p.json.fields['Borrador IA'] || '').split('\n')[0])
  .filter(Boolean);

return [{
  json: {
    recordId: registro.id,
    hilo,
    idea: solicitud.idea,
    publico: solicitud.publico,
    indice: fichas.map((f) => `${f.id} | ${f.Tema} | ${f['Categoría']} | ${f['Palabras clave'] || ''}`).join('\n'),
    fichas,
    historial: publicados.length ? publicados.map((g, i) => `${i + 1}. ${g}`).join('\n') : 'Todavía no hay nada publicado.',
  },
}];

