// Claude devuelve {"ids": [...]}. Si la respuesta no se puede leer, uso todas las fichas validadas:
// prefiero un borrador con información de más antes que uno sin datos
const previo = $('Preparar contexto').first().json;
const texto = $json.content?.[0]?.text ?? '';
let ids = [];
try {
  ids = JSON.parse(texto.slice(texto.indexOf('{'), texto.lastIndexOf('}') + 1)).ids || [];
} catch (e) {
  ids = [];
}
let elegidas = previo.fichas.filter((f) => ids.includes(f.id));
if (elegidas.length === 0) elegidas = previo.fichas;

return {
  json: {
    recordId: previo.recordId,
    hilo: previo.hilo,
    idea: previo.idea,
    publico: previo.publico,
    historial: previo.historial,
    fichasIds: elegidas.map((f) => f.id),
    temas: elegidas.map((f) => f.Tema).join(', '),
    contexto: elegidas.map((f) => `### ${f.Tema} (${f['Categoría']})\n${f.Contenido}`).join('\n\n'),
    feedback: '',
    borradorAnterior: '',
    intento: 1,
  },
};

