// La respuesta de Claude tiene que ser un JSON con categoría, post y hashtags.
// Si no lo es, lanzo un error para que el flujo vaya por la ruta de fallo de IA y quede registrado
const intento = $('Preparar nuevo intento').isExecuted
  ? $('Preparar nuevo intento').last().json
  : $('Fichas elegidas').first().json;

const texto = $json.content?.[0]?.text ?? '';
let r;
try {
  r = JSON.parse(texto.slice(texto.indexOf('{'), texto.lastIndexOf('}') + 1));
} catch (e) {
  throw new Error('La respuesta de Claude no es un JSON válido');
}
if (!r.post || r.post.trim().length < 80) throw new Error('Claude devolvió un post vacío o demasiado corto');

const categorias = ['Educativo', 'Producto', 'Caso de uso', 'Opinión'];
const hashtags = (Array.isArray(r.hashtags) ? r.hashtags : []).slice(0, 3).join(' ');

return {
  json: {
    ...intento,
    post: r.post.trim(),
    categoria: categorias.includes(r.categoria) ? r.categoria : 'Educativo',
    hashtags,
    textoFinal: `${r.post.trim()}\n\n${hashtags}`.trim(),
    tokens: ($json.usage?.input_tokens ?? 0) + ($json.usage?.output_tokens ?? 0),
  },
};

