// El revisor ha pedido cambios: vuelvo a mandar a Claude la misma idea y las mismas fichas,
// con su comentario y el borrador anterior, y sumo un intento (el límite lo controla "¿Quedan intentos?")
const base = $('Fichas elegidas').first().json;
const ultimo = $('Interpretar respuesta').last().json;
const cambios = $('Pedir cambios al revisor').last().json.data?.text ?? '';

return [{
  json: {
    ...base,
    feedback: String(cambios).trim(),
    borradorAnterior: ultimo.post,
    intento: ultimo.intento + 1,
  },
}];
